root.classList.add('inventory-work-frame');header.classList.add('qif-header');header.querySelector('h1').textContent='재고현황 등록 및 조회';header.querySelector('p')?.remove();header.querySelector('.date-badge')?.remove();header.append(tools);shell.prepend(header);
const search=filters.querySelector('.search-input'),dates=[...filters.querySelectorAll('input[type=date]')];search.placeholder='전체';dates[0].dataset.inventoryPeriod='start';dates[1].dataset.inventoryPeriod='end';
function input(cls){const el=document.createElement('input');el.className=cls;el.placeholder='전체';return el;}
