function field(name,el){const label=document.createElement('label');label.className='qif-field';const text=document.createElement('span');text.textContent=name;label.append(text,el);return label;}
const kind=select('qif-category',category),code=input('qif-code'),item=input('qif-item'),lot=input('qif-lot'),quality=select('qif-quality',status),period=document.createElement('div');period.className='qif-period';
period.append(...dates);const dateButton=document.createElement('button');dateButton.type='button';dateButton.className='qif-period-trigger';dateButton.setAttribute('aria-label','입고기간 선택');dateButton.setAttribute('aria-haspopup','dialog');dateButton.setAttribute('aria-expanded','false');dateButton.innerHTML='<span class="qif-period-value">기간 선택</span><span aria-hidden="true">▦</span>';period.append(dateButton);
const grid=document.createElement('div');grid.className='qif-grid';grid.append(field('구분',kind),field('품목코드',code),field('품목명',item),field('LOT NO',lot),field('상태',quality),field('입고기간',period));filters.replaceChildren(grid);
const bulk=document.createElement('div');bulk.className='qif-bulk';bulk.hidden=true;bulk.innerHTML='<button class="qif-selected-print" type="button">선택 인쇄</button><button class="qif-selected-mail" type="button">선택 메일 전송</button><button class="qif-selected-delete" type="button" disabled title="재고 원장을 삭제하는 기능은 지원하지 않습니다.">선택 삭제</button>';toolbar.append(bulk);
const heading=document.createElement('div');heading.className='qif-list-head';heading.innerHTML='<strong>▸ 재고 현황</strong><div class="qif-tools"><button type="button" class="qif-clear">조건 지우기</button><button type="button" class="qif-search" aria-label="조회" data-work-tooltip="조회"><svg width="17" height="17" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" aria-hidden="true"><circle cx="8.5" cy="8.5" r="5.75"/><path d="m13 13 4 4"/></svg></button><button type="button" class="qif-toggle" aria-label="재고 현황 접기" aria-expanded="true" aria-controls="qif-list qif-pager" data-work-tooltip="접기"><svg width="16" height="16" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="m5 7.5 5 5 5-5"/></svg></button></div>';wrap.before(heading);wrap.id='qif-list';
const pager=document.createElement('div');pager.className='qif-pager';pager.id='qif-pager';wrap.after(pager);
table.tHead.rows[0].innerHTML='<th><input type="checkbox" class="qif-all" aria-label="조회된 재고 전체 선택"></th>'+['No.','구분','품목코드','품목명','LOT NO','현재고','단위','상태','비고'].map(v=>'<th>'+v+'</th>').join('');
let records=[],page=1,loaded=false,error='',serial=0,controller=null;const selected=new Set();
const controls=[kind,code,item,lot,quality,search,...dates];
function matches(){const contains=(value,q)=>String(value??'').toLowerCase().includes(q.trim().toLowerCase());return records.filter(r=>(!kind.value||r.category===kind.value)&&contains(r.item_code,code.value)&&contains(r.item_name,item.value)&&contains(r.lot_no,lot.value)&&(!quality.value||r.quality_status===quality.value)&&contains([r.item_code,r.item_name,r.lot_no,r.location_code,r.supplier].join(' '),search.value)&&(!dates[0].value||String(r.received_at||'').slice(0,10)>=dates[0].value)&&(!dates[1].value||(!!r.received_at&&String(r.received_at).slice(0,10)<=dates[1].value)));}
const values=r=>[category[r.category]||r.category||'—',r.item_code||'—',r.item_name||'—',r.lot_no||'—',r.quantity??'—',r.unit||'—',status[r.quality_status]||r.quality_status||'—'];
function updateSelection(){const list=matches(),count=list.filter(r=>selected.has(identity(r))).length,all=root.querySelector('.qif-all');all.checked=!!list.length&&count===list.length;all.indeterminate=count>0&&count<list.length;bulk.hidden=!selected.size;for(const [cls,title] of [['print','선택 인쇄'],['mail','선택 메일 전송'],['delete','선택 삭제']])bulk.querySelector('.qif-selected-'+cls).textContent=title+' ('+selected.size+')';body.querySelectorAll('.qif-check').forEach(box=>box.checked=selected.has(box.closest('tr').dataset.stockKey));}
function render(){const list=matches(),pages=Math.max(1,Math.ceil(list.length/10));page=Math.max(1,Math.min(page,pages));body.innerHTML=list.slice((page-1)*10,page*10).map((r,i)=>'<tr data-stock-key="'+esc(identity(r))+'"><td><input type="checkbox" class="qif-check" aria-label="'+((page-1)*10+i+1)+'번 재고 선택"></td><td>'+((page-1)*10+i+1)+'</td>'+values(r).map((v,n)=>'<td'+(n===3?' title="보관위치: '+esc(r.location_code||'미등록')+'"':'')+'>'+esc(n===4&&Number.isFinite(Number(v))?Number(v).toLocaleString('ko-KR',{maximumFractionDigits:6}):v)+'</td>').join('')+'<td><span class="qif-row-actions"><button type="button" data-row-action="print">인쇄</button><button type="button" data-row-action="edit">수정</button><button type="button" class="qif-row-delete" disabled title="재고 원장을 삭제하는 기능은 지원하지 않습니다.">삭제</button></span></td></tr>').join('');
if(!list.length)body.innerHTML='<tr><td colspan="10" class="qif-empty">'+esc(error||(loaded?'조회된 재고 내역이 없습니다.':'재고 데이터를 불러오는 중입니다.'))+'</td></tr>';pager.replaceChildren();const add=(label,n,disabled)=>{const button=document.createElement('button');button.type='button';button.textContent=label;button.disabled=disabled;button.classList.toggle('active',n===page&&/^\d+$/.test(label));button.onclick=()=>{page=n;render();};pager.append(button);};add('‹',page-1,page===1);const from=Math.max(1,Math.min(page-2,pages-4));for(let n=from;n<=Math.min(pages,from+4);n++)add(String(n),n,false);add('›',page+1,page===pages);updateSelection();}
async function request(url,options={}){const response=await fetch(url,{credentials:'same-origin',cache:'no-store',...options}),result=await response.json().catch(()=>({}));if(!response.ok||result.success===false)throw Error(result.message||'재고 조회 실패 ('+response.status+')');return result.data??result;}
async function load(){const token=++serial;controller?.abort();controller=new AbortController();error='';try{const data=await request('/api/inventory/stock',{signal:controller.signal});if(token!==serial)return;if(!Array.isArray(data))throw Error('재고 응답 형식을 확인해 주세요.');records=data;loaded=true;const valid=new Set(records.map(identity));for(const key of selected)if(!valid.has(key))selected.delete(key);page=1;render();}catch(e){if(token!==serial||e.name==='AbortError')return;error=e.message;body.innerHTML='<tr><td colspan="10" class="qif-empty" role="alert">'+esc(error)+'</td></tr>';}}
function unfold(){shell.classList.remove('qif-folded');const button=root.querySelector('.qif-toggle');button.setAttribute('aria-expanded','true');button.dataset.workTooltip='접기';button.setAttribute('aria-label','재고 현황 접기');}
root.querySelector('.qif-search').onclick=()=>{unfold();load();};root.querySelector('.qif-clear').onclick=()=>{controls.forEach(el=>el.value='');dateButton.querySelector('.qif-period-value').textContent='기간 선택';page=1;render();};root.querySelector('.qif-toggle').onclick=()=>{if(shell.classList.contains('qif-folded'))unfold();else{shell.classList.add('qif-folded');const button=root.querySelector('.qif-toggle');button.setAttribute('aria-expanded','false');button.dataset.workTooltip='펼침';button.setAttribute('aria-label','재고 현황 펼침');}};
controls.forEach(el=>el.addEventListener(el.tagName==='SELECT'||el.type==='date'?'change':'input',()=>{page=1;render();}));root.querySelector('.qif-all').onchange=event=>{matches().forEach(r=>event.target.checked?selected.add(identity(r)):selected.delete(identity(r)));updateSelection();};body.addEventListener('change',event=>{if(!event.target.matches('.qif-check'))return;const key=event.target.closest('tr').dataset.stockKey;event.target.checked?selected.add(key):selected.delete(key);updateSelection();});
function printRows(rows){if(!rows.length)return;const win=window.open('','_blank');if(!win){alert('팝업을 허용한 후 다시 인쇄해 주세요.');return;}win.document.open();win.document.write('<!doctype html><html lang="ko"><meta charset="UTF-8"><title>재고 현황</title><style>@page{size:A4 landscape;margin:12mm}body{font:12px Arial,"Malgun Gothic",sans-serif;color:#243e59}h1{text-align:center}table{width:100%;border-collapse:collapse}td,th{border:1px solid #bdcddd;padding:8px;text-align:center}th{background:#eaf2fa}tr{break-inside:avoid}.tools{text-align:right;margin-bottom:12px}@media print{.tools{display:none}}</style><div class="tools"><button id="qif-print-now">인쇄</button></div><h1>나모케미칼 재고 현황</h1><table><thead><tr>'+['No.','구분','품목코드','품목명','LOT NO','현재고','단위','상태','보관위치'].map(v=>'<th>'+v+'</th>').join('')+'</tr></thead><tbody>'+rows.map((r,i)=>'<tr>'+[i+1,...values(r),r.location_code||'—'].map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')+'</tbody></table></html>');win.document.close();const print=()=>{if(!win.closed){win.focus();win.print();}};win.document.getElementById('qif-print-now').onclick=print;Promise.resolve(win.document.fonts?.ready).then(()=>{if(!win.closed)win.requestAnimationFrame(()=>win.requestAnimationFrame(print));});}
