async function edit(row){if(document.getElementById('qif-edit-dialog'))return;const dialog=document.createElement('dialog');dialog.id='qif-edit-dialog';dialog.setAttribute('aria-label','재고 수정');dialog.innerHTML='<form><h2>재고 수정</h2><p>'+esc(row.item_name||row.item_code)+' · LOT '+esc(row.lot_no)+' · '+esc(row.location_code||'위치 미등록')+'</p><p>현재고 '+esc(row.quantity)+' '+esc(row.unit||'')+' / '+esc(status[row.quality_status]||row.quality_status)+'</p><label>실사수량<input type="number" name="quantity" min="0" step="any" value="'+esc(row.quantity)+'" required></label><label>조정 사유<input name="reason" required></label><p class="qif-edit-message" role="status"></p><footer><button type="button">취소</button><button type="submit">저장</button></footer></form>';document.body.append(dialog);let saving=false;const close=()=>{if(!saving){dialog.close();dialog.remove();}};dialog.querySelector('button[type=button]').onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();close();});dialog.showModal();dialog.querySelector('form').onsubmit=async event=>{event.preventDefault();if(saving)return;const actual=Number(dialog.querySelector('[name=quantity]').value),reason=dialog.querySelector('[name=reason]').value.trim();if(!Number.isFinite(actual)||actual<0||!reason)return;if(!row.item_code||!row.lot_no||!row.location_code){dialog.querySelector('.qif-edit-message').textContent='품목·LOT·보관위치를 확인해 주세요.';return;}saving=true;dialog.querySelector('button[type=submit]').disabled=true;try{await request('/api/inventory/counts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({itemCode:row.item_code,lotNo:row.lot_no,locationCode:row.location_code,qualityStatus:row.quality_status,actualQty:actual,reason})});dialog.close();dialog.remove();await load();}catch(e){dialog.querySelector('.qif-edit-message').textContent=e.message;saving=false;dialog.querySelector('button[type=submit]').disabled=false;}};}
body.addEventListener('click',event=>{const button=event.target.closest('[data-row-action]');if(!button)return;event.stopPropagation();const row=records.find(r=>identity(r)===button.closest('tr').dataset.stockKey);if(!row)return;if(button.dataset.rowAction==='print')printRows([row]);else edit(row);});
